import{_ as t}from"./chunks/kataloge-floskeln-01.UgvR68IG.js";import{_ as i,o as a,c as s,a3 as l,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/unterricht-kataloge/kataloge-floskeln-02.png",d="/bilder/unterricht-kataloge/kataloge-floskeln-03.png",u="/bilder/unterricht-kataloge/kataloge-floskeln-04.png",c="/bilder/unterricht-kataloge/kataloge-floskeln-05.png",z=JSON.parse('{"title":"Floskeln und Platzhalter verwalten","description":"","frontmatter":{"title":"Floskeln und Platzhalter verwalten","source_pageid":258,"source_revision":5450},"headers":[],"relativePath":"schild3/unterricht-kataloge/floskeln-bearbeiten-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/floskeln-bearbeiten-schulbezogene-kataloge.md"}'),g={name:"schild3/unterricht-kataloge/floskeln-bearbeiten-schulbezogene-kataloge.md"};function h(k,r,p,m,f,b){return a(),s("div",null,[...r[0]||(r[0]=[l('<h1 id="floskeln-und-platzhalter-verwalten" tabindex="-1">Floskeln und Platzhalter verwalten <a class="header-anchor" href="#floskeln-und-platzhalter-verwalten" aria-label="Permalink to &quot;Floskeln und Platzhalter verwalten&quot;">​</a></h1><p>Hinterlegen Sie wiederkehrende Bemerkungen mit Kürzeln und ordnen Sie diese Floskelgruppen zu. Die Textbausteine stehen anschließend in den passenden Eingabefeldern zur Verfügung.</p><p>In SchILD-NRW gibt es sogenannte Floskeln. Dies sind wiederkehrende Bemerkungen, die in Zeugnisbemerkungen, Bemerkungen zum Arbeits- und Sozialverhalten, Angaben zum außerunterrichtlichen Engagement oder den fachbezogenen Bemerkungen vorkommen können. Außerdem können Floskeln für Textzeugnisse angelegt werden.</p><p>Um diese Bemerkungen nicht immer eintippen zu müssen, können sie in SchILD-NRW mit einem Kürzel hinterlegt werden und so im Zeugnisdruck schnell aufgerufen werden.</p><h2 id="verwaltung-von-floskeln" tabindex="-1">Verwaltung von Floskeln <a class="header-anchor" href="#verwaltung-von-floskeln" aria-label="Permalink to &quot;Verwaltung von Floskeln&quot;">​</a></h2><h3 id="floskelgruppen" tabindex="-1">Floskelgruppen <a class="header-anchor" href="#floskelgruppen" aria-label="Permalink to &quot;Floskelgruppen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-floskeln-01.png"><img src="'+t+'" alt="Grundansicht der Floskelverwaltung unter Kataloge ➜ &quot;Floskeln&quot; bearbeiten." loading="lazy"></a></p><p><em>Grundansicht der Floskelverwaltung unter Kataloge ➜ &quot;Floskeln&quot; bearbeiten.</em></p><p>Floskeln sind in Floskelgruppen sortiert. Diese Gruppen werden automatisch z. B. bei Eingabe in den jeweiligen Bemerkungsfenstern bei der Zeugnisvorbereitung (Schüler ➜ Akt. Quartal/Halbjahr ➜ Bemerkungen) vorausgewählt, so dass die gewünschten Floskeln schneller gefunden werden können.</p><p>Im Beispiel ist die Floskelgruppe &quot;AUE: Floskeln für außerunterrichtliches Engagement&quot; ausgewählt.</p><p><a href="/bilder/unterricht-kataloge/kataloge-floskeln-02.png"><img src="'+o+'" alt="Bearbeitung von Floskelgruppen." loading="lazy"></a></p><p><em>Bearbeitung von Floskelgruppen.</em></p><p>Durch Klick auf &quot;Floskelgruppen zeigen&quot; können alle Floskelgruppen bearbeitet werden.</p><p>Hier können individuelle Farben ausgewählt werden. Außerdem können zu einer Obergruppe neue Floskelgruppen angelegt werden.</p><p>So kann in den Bemerkungsfenstern bei der Zeugnisvorbereitung gezielter unterteilt und gesteuert werden, welche Floskeln dort erscheinen.</p><p>Floskeln der Obergruppe &quot;Allgemein&quot; erscheinen in allen Bemerkungsfeldern.</p><p>Für die Bezeichnung können maximal vier Buchstaben/Ziffern verwendet werden. Das Feld &quot;Bezeichnung&quot; muss ebenfalls ausgefüllt sein.</p>',17),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Ohne zugeordnete "),e("strong",null,"Obergruppe"),n(" erscheinen diese Floskelgruppe und ihre Floskeln in den Zeugnis-Bemerkungsfeldern nur, wenn Sie dort den Filter ausschalten.")])],-1),e("h3",{id:"floskeln",tabindex:"-1"},[n("Floskeln "),e("a",{class:"header-anchor",href:"#floskeln","aria-label":'Permalink to "Floskeln"'},"​")],-1),e("p",null,'In der Grundansicht des Katalogs "Floskeln bearbeiten" können über die Schaltflächen am oberen Rand neue Floskeln angelegt bzw. bestehende Floskeln gelöscht oder bearbeitet werden.',-1),e("p",null,"Bei Neuanlage einer Floskel muss das Feld des Floskeltexts ausgefüllt werden. Das Feld des Kürzels wird von SchILD-NRW automatisch ausgefüllt, wenn keine Eingabe erfolgt.",-1),e("p",null,"Es empfiehlt sich aber, hier ein einfach zu merkendes Kürzel einzustellen, da dieses bei der Eingabe der Zeugnisbemerkungen automatisch ersetzt werden kann.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Damit Daten bei Änderung oder Neuanlage einer Floskel übernommen werden, muss entweder mit der Maus zu einem anderen Datensatz gewechselt werden oder die Haken-Schaltfläche am oberen Rand geklickt werden.")],-1),l(`<h3 id="platzhalter" tabindex="-1">Platzhalter <a class="header-anchor" href="#platzhalter" aria-label="Permalink to &quot;Platzhalter&quot;">​</a></h3><p>In den Floskeln können drei Platzhalter verwendet werden, die dann vom Programm automatisch ersetzt werden. Diese Platzhalter müssen exakt so geschrieben werden. Sie werden von Dollar-Zeichen ($) eingefasst:</p><ul><li>$Vorname$</li><li>$Name$ (fügt den Nachnamen ein)</li><li>$Nachname$ (fügt den Nachnamen ein)</li></ul><p>Daneben können noch geschlechtsspezifische Platzhalter verwendet werden, die dann je nach Geschlecht des Schülers oder der Schülerin eingesetzt werden.</p><p>Diese Platzhalter können frei gewählt werden. Sie werden von Und-Zeichen (&amp;) eingefasst. Die zuerst genannte männliche Form wird mit einem Prozent-Zeichen (%) von der weiblichen Form getrennt:</p><p>Beispiel:</p><pre><code> &amp;Klassenbuchführer%Klassenbuchführerin&amp;  (&amp;männliche_Bezeichnung%weibliche_Bezeichnung&amp;)
</code></pre><h3 id="massenhaftes-bearbeiten-von-floskeln" tabindex="-1">Massenhaftes Bearbeiten von Floskeln <a class="header-anchor" href="#massenhaftes-bearbeiten-von-floskeln" aria-label="Permalink to &quot;Massenhaftes Bearbeiten von Floskeln&quot;">​</a></h3><p><strong>Alle Floskeln löschen</strong></p><p>Durch Klick auf diese Schaltfläche werden nach Bestätigung einer Abfrage alle Floskeln gelöscht, die in der momentanen Ansicht gezeigt werden.</p><p><strong>Floskeln importieren</strong></p><p><a href="/bilder/unterricht-kataloge/kataloge-floskeln-03.png"><img src="`+d+'" alt="Import und Export von Floskel mittels Excel-Dateien." loading="lazy"></a></p><p><em>Import und Export von Floskel mittels Excel-Dateien.</em></p><p><a href="/bilder/unterricht-kataloge/kataloge-floskeln-04.png"><img src="'+u+'" alt="Ansicht einer Excel-Datei zum Import in SchILD." loading="lazy"></a></p><p><em>Ansicht einer Excel-Datei zum Import in SchILD.</em></p><p>Durch Klick auf diese Schaltfläche kann eine Excel-Datei ausgewählt werden, die vorbereitete Floskeln enthält.</p><p>Dies bietet den Vorteil einer einfacheren Bearbeitung der Floskellisten im Gegensatz zur Bearbeitung direkt in SchILD.</p><p>Außerdem können Floskellisten importiert werden, die auf der Schulverwaltungsseite zur Verfügung gestellt werden.</p><p>Insbesondere können so zügig Vorlagen für Textzeugnisse importiert werden, die mit den Report-/Zeugnispaketen der entsprechenden Schulformen zur Verfügung gestellt werden.</p><p><strong>Floskeln exportieren</strong></p><p>Umgekehrt können die in der aktuellen Ansicht gezeigten Floskeln in eine Excel-Datei exportiert werden.</p><p>Dies sollte insbesondere nach umfangreichen Änderungen an den Floskeln geschehen, um die Daten zu sichern.</p><p>Als Standard-Ausgabeverzeichnis ist das SVWS-Arbeitsverzeichnis ausgewählt.</p><p>Natürlich kann auch jedes andere Verzeichnis auf dem Datenträger, einer Serveradresse (bei entsprechender Berechtigung) oder einem externen Datenträger gewählt werden.</p>',24),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Beachten Sie, die auf Zeugnissen verwendeten Floskeln endgültig auf der Schulkonferenz beschlossen werden.")],-1),l('<h2 id="verwendung-von-floskeln" tabindex="-1">Verwendung von Floskeln <a class="header-anchor" href="#verwendung-von-floskeln" aria-label="Permalink to &quot;Verwendung von Floskeln&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-floskeln-05.png"><img src="'+c+'" alt="Ansicht des Editors zur Eingabe von Floskel an verschiedenen Stellen in SchILD." loading="lazy"></a></p><p><em>Ansicht des Editors zur Eingabe von Floskel an verschiedenen Stellen in SchILD.</em></p><p>An verschiedenen Stellen in SchILD können die Floskeln im Editor genutzt werden. Der Editor für diese Bemerkungen filtert nun nach Floskelgruppe vor, je nachdem an welcher Stelle in SchILD der Editor aufgerufen wird.</p><p>Der Editor steht an folgenden Stellen zur Verfügung:</p><ul><li>Schüler ➜ Akt. Quartal/Halbjahr ➜ Bemerkungen</li><li>Schüler ➜ Akt. Quartal/Halbjahr ➜ Leistungsdaten ➜ Fachbez. Leistungsentw.</li><li>Schüler ➜ Vermerke (Doppelklick in das Feld Bemerkung)</li><li>Schüler ➜ Fördermaßnahmen (Doppelklick in ein Bemerkungsfeld)</li></ul><p>Die Filterung kann dann über &quot;Filteroptionen&quot; manuell aufgehoben oder geändert werden. Zusätzlich kann für eine bessere Lesbarkeit z. B. auf Zeugnissen angewählt werden, dass Vornamen nicht mehrfach genannt werden.</p>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die fachbezogene Leistungsentwicklung steht erst zur Verfügung, wenn sie unter Verwaltung ➜ Einstellungen ➜ Globale Einstellungen: Allgemeines ➜ Ansicht aktiviert wurde.")],-1),e("p",null,"Der Editor ermöglicht es außerdem, die Tastatureingabe automatisch auf Floskeln zu überprüfen.",-1),e("p",null,"Ist dies am unteren Rand des Editors aktiviert, genügt es, das Kürzel der Floskel einzugeben und dann die Eingabetaste zu drücken.",-1),e("p",null,"Der Floskeltext wird automatisch eingesetzt. Diese Option bietet sich besonders dann an, wenn Floskeln häufig verwendet werden.",-1),e("p",null,"Bei der fachbezogenen Leistungsentwicklung kann ein Jahrgang und ein Niveau vergeben werden. So können die Kategorien für den Zeugnisdruck bei Textzeugnissen aufgebaut werden.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Sollen Floskeln zum Beispiel als Zeugnisbemerkungen für ganze Schülergruppen eingetragen werden, sollte anstelle einer manuellen Eingabe bei jeder einzelnen Schülerin oder jedem einzelnen Schüler der entsprechende Gruppenprozess verwendet werden. Verwenden Sie "),e("em",null,"Gruppenprozesse ➜ Noten, Zeugnisvorbereitung"),n(" ➜ "),e("strong",null,"Zeugnisbemerkungen eintragen"),n(".")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Floskeln_bearbeiten_(Schulbezogene_Kataloge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5450.")],-1)])])}const F=i(g,[["render",h]]);export{z as __pageData,F as default};
